#!/usr/bin/env python3
"""Sidecar CLI for tiny_econ - generated by fd-daas-datasource-builder.
Imports the original package (tiny_econ.api); does not modify it.
Each command prints JSON records. Install deps with: uv run --with <deps> python daas_cli.py ..."""
import json

import click

try:
    import pandas as pd
except ImportError:
    pd = None


def _emit(result):
    if pd is not None and isinstance(result, pd.DataFrame):
        print(result.to_json(orient="records", force_ascii=False, date_format="iso"))
    elif isinstance(result, (list, tuple)):
        print(json.dumps(list(result), ensure_ascii=False, default=str))
    elif isinstance(result, dict):
        print(json.dumps(result, ensure_ascii=False, default=str))
    else:
        print(json.dumps(str(result), ensure_ascii=False))


@click.group()
def cli():
    """Tiny Econ (test fixture) sidecar CLI (auto-generated)."""
    pass


@cli.command("get-cpi-series", help="获取 CPI 同比序列数据 (月度)。模拟 api.example.com/cpi，无真实上游。")
@click.option("--country", "country", default='CN', help="ISO alpha-2 国家代码, e.g. CN / US")
@click.option("--start-year", "start_year", type=int, default=2010, help="起始年份")
@click.option("--end-year", "end_year", type=int, default=2024, help="结束年份")
def get_cpi_series_cmd(country, start_year, end_year):
    """获取 CPI 同比序列数据 (月度)。模拟 api.example.com/cpi，无真实上游。"""
    import importlib
    mod = importlib.import_module("tiny_econ.api")
    fn = getattr(mod, "get_cpi_series")
    result = fn(country=country, start_year=start_year, end_year=end_year)
    _emit(result)


